import GPXAnalyzer from "./GPXAnalyzer";
import{useState,useEffect,useRef}from"react";
const T={bg:"#0d0f14",surface:"#13161e",card:"#1a1e2a",hi:"#1f2435",border:"#252b3b",accent:"#3b82f6",dim:"#1d3f7a",red:"#ef4444",green:"#22c55e",yellow:"#eab308",orange:"#f97316",pink:"#ec4899",pinkDim:"#4a1530",white:"#f1f5f9",text:"#cbd5e1",muted:"#64748b",uci:"#f59e0b",ro1:"#002B7F",ro2:"#FCD116",ro3:"#CE1126",zc:["#22c55e","#4ade80","#eab308","#f97316","#ef4444"]};
function Logo({s=38}){const id="l"+s;return(<svg width={s} height={s} viewBox="0 0 38 38" fill="none"><defs><linearGradient id={id} x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#002B7F"/><stop offset="50%" stopColor="#3b82f6"/><stop offset="100%" stopColor="#CE1126"/></linearGradient><linearGradient id={id+"s"} x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#CE1126" stopOpacity="0"/><stop offset="60%" stopColor="#FCD116" stopOpacity="0.9"/><stop offset="100%" stopColor="#fff" stopOpacity="0"/></linearGradient></defs><circle cx="19" cy="19" r="16.5" stroke={`url(#${id})`} strokeWidth="2.2" fill="none"/><circle cx="19" cy="19" r="10.5" stroke="#1e3a5f" strokeWidth="1" fill="none"/><circle cx="19" cy="19" r="3" fill={`url(#${id})`}/><circle cx="19" cy="19" r="1.4" fill="#0d0f14"/>{[0,30,60,90,120,150].map((a,i)=>{const r=Math.PI*a/180;return <line key={i} x1={19+3.2*Math.cos(r)} y1={19+3.2*Math.sin(r)} x2={19+10.2*Math.cos(r)} y2={19+10.2*Math.sin(r)} stroke={i%2===0?"#3b82f6":"#1d4ed8"} strokeWidth="1" strokeLinecap="round"/>;})}<line x1="0" y1="15" x2="4" y2="15" stroke={`url(#${id}s)`} strokeWidth="1.5" strokeLinecap="round"/><line x1="0" y1="19" x2="2.5" y2="19" stroke={`url(#${id}s)`} strokeWidth="2" strokeLinecap="round"/><line x1="0" y1="23" x2="4" y2="23" stroke={`url(#${id}s)`} strokeWidth="1.5" strokeLinecap="round"/><circle cx="19" cy="2.8" r="1.4" fill="#FCD116" opacity="0.9"/></svg>);}
const useAnim=dep=>{const[v,setV]=useState(false);useEffect(()=>{setV(false);const t=setTimeout(()=>setV(true),40);return()=>clearTimeout(t);},[dep]);return v;};
const saveU=u=>{try{localStorage.setItem("cc_user",JSON.stringify(u));}catch(e){}};
const loadU=()=>{try{const s=localStorage.getItem("cc_user");return s?JSON.parse(s):null;}catch(e){return null;}};
const clearU=()=>{try{localStorage.removeItem("cc_user");}catch(e){}};
const sh=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b;};
const SEXO=[{v:"masculin",l:"Masculin",i:"♂️",c:"#3b82f6"},{v:"feminin",l:"Feminin",i:"♀️",c:"#ec4899"}];
const BIKEO=[{v:"sosea",l:"Șosea",i:"🚴",c:T.accent},{v:"gravel",l:"Gravel",i:"🪨",c:T.orange},{v:"mtb",l:"MTB",i:"🏔️",c:T.green},{v:"cx",l:"CX",i:"🌾",c:T.yellow}];
function Card({children,style,ac,pk}){return <div style={{background:T.card,borderRadius:16,border:`1px solid ${pk?T.pinkDim:ac?T.dim:T.border}`,borderLeft:pk?`3px solid ${T.pink}`:ac?`3px solid ${T.accent}`:undefined,overflow:"hidden",...style}}>{children}</div>;}
function Badge({label,color=T.accent}){return <span style={{background:color+"22",color,border:`1px solid ${color}44`,fontSize:10,fontWeight:700,padding:"2px 8px",borderRadius:6,letterSpacing:"0.06em",textTransform:"uppercase",whiteSpace:"nowrap"}}>{label}</span>;}
function Pill({icon,value,label,color=T.accent}){return <div style={{background:T.hi,borderRadius:12,padding:"12px 14px",textAlign:"center",flex:1}}><div style={{fontSize:18,marginBottom:2}}>{icon}</div><div style={{color,fontWeight:800,fontSize:17,lineHeight:1}}>{value}</div><div style={{color:T.muted,fontSize:10,marginTop:3,fontWeight:600}}>{label}</div></div>;}
function Divider(){return <div style={{height:1,background:T.border,margin:"20px 0"}}/>;}
function Btn({children,onClick,variant="primary",disabled,style}){return <button onClick={onClick} disabled={disabled} style={{width:"100%",background:disabled?T.border:variant==="primary"?T.accent:variant==="ghost"?"transparent":T.card,border:variant==="ghost"?`1px solid ${T.border}`:"none",borderRadius:14,padding:"15px 20px",color:disabled?T.muted:"#fff",fontSize:15,fontWeight:700,cursor:disabled?"not-allowed":"pointer",...style}}>{children}</button>;}
function NInput({label,value,onChange,min,max,unit}){return <div style={{flex:1}}><div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:6,textTransform:"uppercase",letterSpacing:"0.08em"}}>{label}</div><div style={{display:"flex",alignItems:"center",background:T.hi,borderRadius:10,border:`1px solid ${T.border}`,overflow:"hidden"}}><button onClick={()=>onChange(Math.max(min??0,value-1))} style={{background:"none",border:"none",color:T.muted,fontSize:20,padding:"0 12px",cursor:"pointer",height:44}}>−</button><input type="number" value={value} onChange={e=>onChange(+e.target.value)} style={{background:"none",border:"none",color:T.white,fontWeight:800,fontSize:18,textAlign:"center",width:"100%",outline:"none",height:44}}/><div style={{color:T.muted,fontSize:12,paddingRight:6}}>{unit}</div><button onClick={()=>onChange(Math.min(max??9999,value+1))} style={{background:"none",border:"none",color:T.muted,fontSize:20,padding:"0 12px",cursor:"pointer",height:44}}>+</button></div></div>;}
function Inp({label,type="text",value,onChange,placeholder,icon,error,right}){const[f,setF]=useState(false);return <div style={{marginBottom:16}}>{label&&<div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:6,textTransform:"uppercase",letterSpacing:"0.08em"}}>{label}</div>}<div style={{display:"flex",alignItems:"center",background:T.hi,borderRadius:12,border:`1px solid ${error?T.red:f?T.accent:T.border}`,overflow:"hidden"}}>{icon&&<div style={{padding:"0 12px",fontSize:18}}>{icon}</div>}<input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} onFocus={()=>setF(true)} onBlur={()=>setF(false)} style={{background:"none",border:"none",color:T.white,fontSize:15,padding:"13px 14px",width:"100%",outline:"none"}}/>{right&&<div style={{paddingRight:12}}>{right}</div>}</div>{error&&<div style={{color:T.red,fontSize:11,marginTop:4}}>{error}</div>}</div>;}
function Sel({label,value,onChange,options}){return <div style={{marginBottom:16}}>{label&&<div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:6,textTransform:"uppercase",letterSpacing:"0.08em"}}>{label}</div>}<select value={value} onChange={e=>onChange(e.target.value)} style={{width:"100%",background:T.hi,border:`1px solid ${T.border}`,borderRadius:12,color:T.white,fontSize:15,padding:"13px 14px",outline:"none",cursor:"pointer"}}>{options.map(o=><option key={o.v} value={o.v} style={{background:T.card}}>{o.l}</option>)}</select></div>;}
function Toggle({label,value,onChange,options}){return <div style={{marginBottom:16}}>{label&&<div style={{color:T.muted,fontSize:11,fontWeight:700,marginBottom:8,textTransform:"uppercase",letterSpacing:"0.08em"}}>{label}</div>}<div style={{display:"flex",gap:8,flexWrap:"wrap"}}>{options.map(o=><button key={o.v} onClick={()=>onChange(o.v)} style={{flex:1,minWidth:70,background:value===o.v?(o.c||T.accent):T.hi,border:`1.5px solid ${value===o.v?(o.c||T.accent):T.border}`,borderRadius:12,padding:"12px 8px",cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"center",gap:4}}><span style={{fontSize:20}}>{o.i}</span><span style={{color:value===o.v?"#fff":T.muted,fontSize:11,fontWeight:700}}>{o.l}</span></button>)}</div></div>;}
function Chk({label,checked,onChange,sub}){return <button onClick={()=>onChange(!checked)} style={{width:"100%",background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:12,padding:"4px 0",marginBottom:8}}><div style={{width:22,height:22,borderRadius:6,flexShrink:0,background:checked?T.accent:T.hi,border:`1.5px solid ${checked?T.accent:T.border}`,display:"flex",alignItems:"center",justifyContent:"center"}}>{checked&&<span style={{color:"#fff",fontSize:13,fontWeight:900}}>✓</span>}</div><div style={{textAlign:"left"}}><div style={{color:T.white,fontSize:14,fontWeight:600}}>{label}</div>{sub&&<div style={{color:T.muted,fontSize:11,marginTop:1}}>{sub}</div>}</div></button>;}
function AvatarPic({value,onChange,name,size=88}){const ref=useRef();const ini=(name||"U")[0].toUpperCase();return <div style={{display:"flex",flexDirection:"column",alignItems:"center",marginBottom:size<60?0:20}}><input ref={ref} type="file" accept="image/*" style={{display:"none"}} onChange={e=>{const f=e.target.files[0];if(f){const r=new FileReader();r.onload=ev=>onChange(ev.target.result);r.readAsDataURL(f);}}}/><button onClick={()=>ref.current.click()} style={{background:"none",border:"none",cursor:"pointer",position:"relative"}}><div style={{width:size,height:size,borderRadius:"50%",background:value?"transparent":`linear-gradient(135deg,${T.accent},#6366f1)`,border:`3px solid ${value?T.accent:T.border}`,display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden"}}>{value?<img src={value} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<span style={{color:"#fff",fontSize:size*0.36,fontWeight:900}}>{ini}</span>}</div>{size>60&&<div style={{position:"absolute",bottom:2,right:2,width:26,height:26,borderRadius:"50%",background:T.accent,border:`2px solid ${T.bg}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:13}}>📷</div>}</button>{size>60&&<div style={{color:T.muted,fontSize:12,marginTop:8}}>Apasă pentru a schimba poza</div>}</div>;}

// TICKER
const TKR=["🏁 TDF 2026 — Philipsen câștigă etapa 3","🇷🇴 Campionatele Naționale Șosea — 19-21 Iunie, Sibiu","🔄 Paul Seixas prelungește cu Decathlon-CMA CGM","🏔️ Turul Sibiului UCI 2.1 — 4-7 Iulie","🚴 Netindava Road Grand Tour — 25 Iulie","🏆 Felix Gall lider GC Giro d'Italia 2026"];
function Ticker({items}){const[x,setX]=useState(0);const ra=useRef();const t0=useRef(null);const el=useRef();const txt=items.join("   •   ");useEffect(()=>{t0.current=null;const fn=ts=>{if(!t0.current)t0.current=ts;if(el.current){const w=el.current.scrollWidth/2;setX(((ts-t0.current)*0.032)%w);}ra.current=requestAnimationFrame(fn);};ra.current=requestAnimationFrame(fn);return()=>cancelAnimationFrame(ra.current);},[items]);return(<div style={{background:"#7f1d1d",height:28,display:"flex",alignItems:"center",overflow:"hidden",margin:"0 -16px",marginTop:-18,marginBottom:16}}><style>{`@keyframes bk{0%,100%{opacity:1}50%{opacity:.2}}`}</style><div style={{background:"#CE1126",padding:"0 10px",height:"100%",display:"flex",alignItems:"center",flexShrink:0,gap:5}}><div style={{width:6,height:6,borderRadius:"50%",background:"#FCD116",animation:"bk 1s infinite"}}/><span style={{color:"#fff",fontSize:9,fontWeight:900,letterSpacing:"0.14em"}}>LIVE</span></div><div style={{flex:1,overflow:"hidden",paddingLeft:8}}><div ref={el} style={{display:"inline-block",whiteSpace:"nowrap",transform:`translateX(-${x}px)`,willChange:"transform"}}><span style={{color:"#fecaca",fontSize:11}}>{txt+"     "+txt}</span></div></div></div>);}

