const CL={race:"Cursă",transfer:"Transfer",team:"Echipă",romania:"România"};
function NItem({item,idx}){const[o,setO]=useState(false);const c=CC[item.cat]||T.accent;return(<div style={{background:T.card,borderRadius:14,overflow:"hidden",border:`1px solid ${o?c+"44":T.border}`}}><button onClick={()=>setO(!o)} style={{width:"100%",background:"none",border:"none",padding:"13px 15px",cursor:"pointer",textAlign:"left"}}><div style={{display:"flex",justifyContent:"space-between",gap:8}}><div style={{flex:1}}><div style={{display:"flex",gap:6,marginBottom:6,flexWrap:"wrap",alignItems:"center"}}><Badge label={CL[item.cat]} color={c}/>{item.hot&&<Badge label="🔥" color={T.red}/>}<span style={{color:T.muted,fontSize:10}}>acum {item.time}</span></div><div style={{color:T.white,fontWeight:700,fontSize:14,lineHeight:1.4}}>{item.title}</div></div><span style={{color:T.accent,fontSize:14,flexShrink:0,transform:o?"rotate(180deg)":"none",transition:"transform .2s"}}>⌄</span></div></button>{o&&<div style={{padding:"0 15px 13px"}}><div style={{height:1,background:T.border,marginBottom:10}}/><div style={{color:T.text,fontSize:13,lineHeight:1.7}}>{item.sum}</div></div>}</div>);}
function NewsTab(){const[cat,setCat]=useState("all");const[items,setItems]=useState([]);const[tkr,setTkr]=useState(TKR);const[upd,setUpd]=useState(null);const[rk,setRk]=useState(0);const build=c=>{const pool=c==="all"?NEWS:NEWS.filter(n=>n.cat===c);setItems(sh(pool).slice(0,6));setTkr(sh(TKR));setUpd(new Date().toLocaleTimeString("ro-RO",{hour:"2-digit",minute:"2-digit"}));};useEffect(()=>{build(cat);},[cat,rk]);const NC=[{k:"all",l:"Toate",e:"🌐"},{k:"race",l:"Curse",e:"🏁"},{k:"transfer",l:"Transferuri",e:"🔄"},{k:"romania",l:"România",e:"🇷🇴"}];return(<div><Ticker items={tkr}/><div style={{display:"flex",gap:6,marginBottom:14,overflowX:"auto",paddingBottom:4}}>{NC.map(c=><button key={c.k} onClick={()=>setCat(c.k)} style={{flexShrink:0,padding:"7px 13px",borderRadius:20,border:`1px solid ${cat===c.k?T.accent:T.border}`,background:cat===c.k?T.accent:"transparent",color:cat===c.k?"#fff":T.muted,fontWeight:700,fontSize:12,cursor:"pointer"}}>{c.e} {c.l}</button>)}</div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><span style={{color:T.muted,fontSize:11}}>{upd?`Actualizat ${upd}`:""}</span><button onClick={()=>setRk(k=>k+1)} style={{background:"none",border:`1px solid ${T.border}`,borderRadius:8,padding:"5px 12px",color:T.text,fontSize:12,fontWeight:600,cursor:"pointer"}}>↻ Refresh</button></div><div key={rk+cat} style={{display:"flex",flexDirection:"column",gap:10}}>{items.map((item,i)=><NItem key={item.id} item={item} idx={i}/>)}<div style={{padding:"10px",background:T.hi,borderRadius:12,textAlign:"center"}}><span style={{color:T.muted,fontSize:10}}>Apasă Refresh pentru alte știri</span></div></div></div>);}

