function ProductsTab({user}){const[cat,setCat]=useState("toate");const[gen,setGen]=useState(user?.sex==="feminin"?"f":"b");const[srt,setSrt]=useState("asc");const filtered=PRODS.filter(p=>cat==="toate"||p.cat===cat).filter(p=>gen==="b"?true:p.gen===gen||p.gen==="b").sort((a,b)=>srt==="asc"?a.lvl-b.lvl:b.lvl-a.lvl);return(<div><div style={{display:"flex",gap:8,marginBottom:12}}>{[{v:"b",l:"Toate",i:"🔁"},{v:"f",l:"Feminin ♀",i:"♀️"},{v:"m",l:"Masculin",i:"♂️"}].map(g=><button key={g.v} onClick={()=>setGen(g.v)} style={{flex:1,padding:"9px 4px",borderRadius:12,border:`1.5px solid ${gen===g.v?(g.v==="f"?T.pink:T.accent):T.border}`,background:gen===g.v?(g.v==="f"?T.pinkDim:T.dim):"transparent",color:gen===g.v?"#fff":T.muted,fontWeight:700,fontSize:11,cursor:"pointer"}}>{g.i} {g.l}</button>)}</div><div style={{display:"flex",gap:6,marginBottom:12,overflowX:"auto",paddingBottom:4}}>{PCATS.map(c=><button key={c.k} onClick={()=>setCat(c.k)} style={{flexShrink:0,padding:"6px 12px",borderRadius:20,border:`1px solid ${cat===c.k?T.accent:T.border}`,background:cat===c.k?T.accent:"transparent",color:cat===c.k?"#fff":T.muted,fontWeight:700,fontSize:11,cursor:"pointer"}}>{c.e} {c.l}</button>)}</div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}><span style={{color:T.muted,fontSize:12}}>{filtered.length} produse</span><div style={{display:"flex",gap:6}}><button onClick={()=>setSrt("asc")} style={{padding:"4px 10px",borderRadius:8,border:`1px solid ${srt==="asc"?T.green:T.border}`,background:srt==="asc"?T.green+"22":"transparent",color:srt==="asc"?T.green:T.muted,fontSize:11,fontWeight:600,cursor:"pointer"}}>↑ Buget</button><button onClick={()=>setSrt("desc")} style={{padding:"4px 10px",borderRadius:8,border:`1px solid ${srt==="desc"?T.uci:T.border}`,background:srt==="desc"?T.uci+"22":"transparent",color:srt==="desc"?T.uci:T.muted,fontSize:11,fontWeight:600,cursor:"pointer"}}>↑ Premium</button></div></div><div style={{display:"flex",flexDirection:"column",gap:9}}>{filtered.map(p=><PCard key={p.id} p={p}/>)}</div></div>);}

