const NS={before:[{time:"3–4h înainte",what:"Masă completă",detail:"Paste, orez sau cartofi + proteină slabă.",kcal:"600–800 kcal"},{time:"1–2h înainte",what:"Gustare ușoară",detail:"Banană, biscuiți cu miere sau toast cu gem.",kcal:"200–300 kcal"},{time:"30 min înainte",what:"Gel sau izotonică",detail:"500ml izotonică sau un gel energizant.",kcal:"~100 kcal"}],during:[{time:"La fiecare 45–60 min",what:"Gel sau banană",detail:"55–90g carbo/oră (55g pentru femei)."},{time:"Constant",what:"Hidratare",detail:"500–750 ml/oră normal."},{time:"Curse > 90 min",what:"Electroliți",detail:"Sodiu, magneziu, potasiu — previn crampele."}],after:[{time:"0–30 min",what:"Fereastra de aur",detail:"Proteină + carbohidrați 1:3."},{time:"1–2 ore",what:"Masă completă",detail:"Proteină, carbohidrați, legume."},{time:"Toată ziua",what:"Rehidratare",detail:"Urină galben deschis = hidratat corect."}]};
function NutrTab({user}){const[ph,setPh]=useState("before");const[km,setKm]=useState(80);const[kg,setKg]=useState(user?.weight||75);const[sc,setSc]=useState(false);const f=user?.sex==="feminin";const h=km/25,gels=Math.max(0,Math.floor(h-0.5)),water=Math.round(h*650),carbs=Math.round(h*(f?55:65)),coef=f?0.068:0.075,kcal=Math.round(km*kg*coef);const phases=[{k:"before",l:"Înainte"},{k:"during",l:"În cursă"},{k:"after",l:"Recuperare"}];return(<div><div style={{display:"flex",gap:6,marginBottom:18,overflowX:"auto",paddingBottom:4}}>{phases.map(p=><button key={p.k} onClick={()=>setPh(p.k)} style={{flexShrink:0,padding:"8px 16px",borderRadius:20,border:`1px solid ${ph===p.k?T.accent:T.border}`,background:ph===p.k?T.accent:"transparent",color:ph===p.k?"#fff":T.muted,fontWeight:700,fontSize:13,cursor:"pointer"}}>{p.l}</button>)}</div><div style={{display:"flex",flexDirection:"column",gap:10}}>{NS[ph].map((item,i)=><Card key={i} ac style={{padding:"13px 15px"}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:5,flexWrap:"wrap",gap:4}}><span style={{color:T.accent,fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.08em"}}>{item.time}</span>{item.kcal&&<span style={{color:T.muted,fontSize:11}}>{item.kcal}</span>}</div><div style={{color:T.white,fontWeight:700,fontSize:15,marginBottom:5}}>{item.what}</div><div style={{color:T.text,fontSize:13,lineHeight:1.6}}>{item.detail}</div></Card>)}</div><Divider/><button onClick={()=>setSc(!sc)} style={{width:"100%",background:sc?T.dim:T.card,border:`1px solid ${sc?T.accent:T.border}`,borderRadius:12,padding:"13px 15px",display:"flex",justifyContent:"space-between",alignItems:"center",cursor:"pointer",marginBottom:sc?12:0}}><span style={{color:T.white,fontWeight:700,fontSize:14}}>🧮 Calculator nutriție{f?" ♀":""}</span><span style={{color:T.accent,fontSize:18}}>{sc?"▲":"▼"}</span></button>{sc&&<Card style={{padding:14}}>{f&&<div style={{background:T.pinkDim,border:`1px solid ${T.pink}44`,borderRadius:9,padding:"7px 11px",marginBottom:10,color:T.pink,fontSize:12}}>♀ Calculul e ajustat pentru femei</div>}<div style={{display:"flex",gap:12,marginBottom:14,flexWrap:"wrap"}}><NInput label="Distanță" value={km} onChange={setKm} min={10} max={300} unit="km"/><NInput label="Greutate" value={kg} onChange={setKg} min={40} max={150} unit="kg"/></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}><Pill icon="🔥" value={"~"+kcal} label="kcal arse" color={T.red}/><Pill icon="💧" value={"~"+water+"ml"} label="apă" color={T.accent}/><Pill icon="⚡" value={"~"+carbs+"g"} label="carbo" color={T.yellow}/><Pill icon="🟡" value={gels+" gel"} label="geluri" color={T.orange}/></div></Card>}{f&&<FemSec title="Nutriție pentru femei" tips={FEM.nutr}/>}</div>);}

