const ZD=[{z:1,name:"Recuperare",lo:0,hi:60,desc:"Pedalat lejer după curse grele.",feel:"Poți cânta în timp ce pedalizezi."},{z:2,name:"Anduranță",lo:60,hi:70,desc:"Baza motorului aerob. 70–80% din antrenamente.",feel:"Conversație ușoară, respiri confortabil."},{z:3,name:"Tempo",lo:70,hi:80,desc:"Efort moderat-susținut. Sweet Spot intră parțial.",feel:"Poți vorbi scurt, respiri mai rapid."},{z:4,name:"Prag",lo:80,hi:90,desc:"Crește FTP-ul. Intervale 8–20 min.",feel:"Abia scoți câteva cuvinte."},{z:5,name:"VO₂ Max",lo:90,hi:100,desc:"Sprint și intervale scurte intense.",feel:"Nu poți vorbi. Arsură musculară."}];
function HRTab({user}){const[hrMax,setHrMax]=useState(user?.hrMax||185);const[sex,setSex]=useState(user?.sex||"masculin");const[age,setAge]=useState(user?.age||35);const[az,setAz]=useState(null);const est=sex==="feminin"?226-age:220-age;useEffect(()=>setHrMax(est),[sex,age]);return(<div><Card style={{padding:14,marginBottom:18}}><div style={{color:T.accent,fontWeight:800,fontSize:12,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:12}}>Setează parametrii tăi</div><Toggle label="Sex" value={sex} onChange={setSex} options={SEXO}/><div style={{display:"flex",gap:12,flexWrap:"wrap"}}><NInput label="Vârstă" value={age} onChange={setAge} min={15} max={80} unit="ani"/><NInput label="HR Max real" value={hrMax} onChange={setHrMax} min={100} max={230} unit="bpm"/></div><div style={{marginTop:6,color:T.muted,fontSize:12}}>Formula {sex==="feminin"?"226":"220"}−vârstă: <span style={{color:T.yellow,fontWeight:700}}>{est} bpm</span>{sex==="feminin"&&<span style={{color:T.pink,marginLeft:6}}>♀ ajustat</span>}</div></Card><div style={{display:"flex",flexDirection:"column",gap:8}}>{ZD.map((z,i)=>{const lo=Math.round(z.lo/100*hrMax),hi=Math.round(z.hi/100*hrMax),range=z.lo===0?"< "+hi+" bpm":lo+"–"+hi+" bpm",color=T.zc[i],isO=az===i;return(<div key={i} style={{borderRadius:14,overflow:"hidden",border:`1px solid ${isO?color+"55":T.border}`}}><button onClick={()=>setAz(isO?null:i)} style={{width:"100%",background:isO?T.hi:T.card,border:"none",padding:"13px 15px",cursor:"pointer",display:"flex",alignItems:"center",gap:12}}><div style={{width:32,height:32,borderRadius:8,background:color+"22",border:`1.5px solid ${color}`,display:"flex",alignItems:"center",justifyContent:"center",color,fontWeight:900,fontSize:14,flexShrink:0}}>Z{z.z}</div><div style={{flex:1,textAlign:"left"}}><div style={{color:T.white,fontWeight:700,fontSize:14}}>{z.name}</div><div style={{marginTop:4,background:T.border,borderRadius:3,height:4,overflow:"hidden"}}><div style={{width:z.hi+"%",height:"100%",background:color,borderRadius:3}}/></div></div><div style={{color,fontWeight:800,fontSize:14,flexShrink:0}}>{range}</div></button>{isO&&<div style={{background:T.surface,padding:"11px 15px 13px"}}><div style={{color:T.text,fontSize:13,lineHeight:1.6,marginBottom:8}}>{z.desc}</div><div style={{display:"flex",gap:8,background:T.card,borderRadius:10,padding:"9px 12px"}}><span>💬</span><div style={{color:T.muted,fontSize:12,fontStyle:"italic",lineHeight:1.6}}>{z.feel}</div></div></div>}</div>);})}</div><Divider/><Card style={{padding:14}}><div style={{color:T.yellow,fontWeight:800,fontSize:13,marginBottom:6}}>💡 Regula 80/20</div><div style={{color:T.text,fontSize:13,lineHeight:1.7}}><strong style={{color:T.white}}>80% Zona 2</strong>, 20% intensitate ridicată.{sex==="feminin"&&<span style={{color:T.pink}}> Femeile beneficiază chiar mai mult de Zona 2.</span>}</div></Card>{sex==="feminin"&&<FemSec title="Antrenament pentru femei" tips={FEM.train}/>}</div>);}

