const RACES=[{name:"Campionatele Naționale Șosea 2026",date:"19–21 Iunie",loc:"Județul Sibiu",type:"CAMPIONAT",tc:T.uci,av:true,note:"Cel mai important eveniment al anului. Elite, U23, U19, Juniori.",frc:"https://federatiadeciclism.ro",ins:"https://racehub.ro"},{name:"Turul Sibiului UCI 2.1",date:"4–7 Iulie",loc:"Sibiu",type:"UCI 2.1",tc:T.uci,av:true,note:"Ediția 16. UAE Emirates și Red Bull Bora confirmate. Etapa regină — Bâlea Lac.",frc:"https://federatiadeciclism.ro/calendar/turul-sibiului/",ins:"https://ciclism.sibiu.ro/"},{name:"Păltiniș Challenge",date:"5 Iulie",loc:"Sibiu — Păltiniș",type:"AMATORI",tc:T.green,av:true,note:"Urcarea clasică spre Păltiniș. Accesibilă amatorilor.",frc:"https://federatiadeciclism.ro",ins:"https://federatiadeciclism.ro"},{name:"Transfăgărășan Challenge",date:"6 Iulie",loc:"Sibiu — Bâlea Lac",type:"AMATORI",tc:T.green,av:true,note:"Urcarea Transfăgărășanului. Cel mai spectaculos drum din România.",frc:"https://federatiadeciclism.ro",ins:"https://federatiadeciclism.ro"},{name:"CR Șosea / Netindava Slobozia",date:"25 Iulie",loc:"Slobozia, Bărăgan",type:"CUPA RO",tc:T.accent,av:false,note:"102 km pe câmpia Bărăganului. Teren plat, vântul poate fi factor decisiv.",frc:"https://federatiadeciclism.ro",ins:"https://federatiadeciclism.ro"},{name:"Turul Ținutului Secuiesc UCI 2.2",date:"6–8 August",loc:"Harghita",type:"UCI 2.2",tc:T.uci,av:false,note:"Al doilea eveniment UCI din România în 2026.",frc:"https://federatiadeciclism.ro",ins:"https://federatiadeciclism.ro"}];
function CalTab(){const[sel,setSel]=useState(null);const[flt,setFlt]=useState("toate");const flts=[{k:"toate",l:"Toate"},{k:"amatori",l:"Amatori"},{k:"uci",l:"UCI"},{k:"cupa",l:"Cupă"}];const filt=RACES.filter(r=>{if(flt==="toate")return true;if(flt==="amatori")return r.type==="AMATORI";if(flt==="uci")return r.type.includes("UCI");if(flt==="cupa")return r.type.includes("CUP");return true;});return(<div><div style={{display:"flex",gap:6,marginBottom:14,overflowX:"auto",paddingBottom:4}}>{flts.map(f=><button key={f.k} onClick={()=>{setFlt(f.k);setSel(null);}} style={{flexShrink:0,padding:"7px 14px",borderRadius:20,border:`1px solid ${flt===f.k?T.accent:T.border}`,background:flt===f.k?T.accent:"transparent",color:flt===f.k?"#fff":T.muted,fontWeight:700,fontSize:12,cursor:"pointer"}}>{f.l}</button>)}</div><div style={{display:"flex",flexDirection:"column",gap:8}}>{filt.map((race,i)=><div key={i} style={{borderRadius:14,overflow:"hidden",border:`1px solid ${sel===i?race.tc+"55":T.border}`}}><button onClick={()=>setSel(sel===i?null:i)} style={{width:"100%",background:sel===i?T.hi:T.card,border:"none",padding:"13px 15px",cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:10,textAlign:"left"}}><div style={{flex:1}}><div style={{display:"flex",alignItems:"center",gap:6,marginBottom:5,flexWrap:"wrap"}}><Badge label={race.type} color={race.tc}/>{race.av&&<Badge label="FRC" color={T.green}/>}</div><div style={{color:T.white,fontWeight:700,fontSize:14,lineHeight:1.4,marginBottom:4}}>{race.name}</div><div style={{display:"flex",gap:10}}><span style={{color:T.muted,fontSize:12}}>📅 {race.date}</span><span style={{color:T.muted,fontSize:12}}>📍 {race.loc}</span></div></div><span style={{color:T.accent,fontSize:16,flexShrink:0,transform:sel===i?"rotate(180deg)":"none",transition:"transform .2s"}}>⌄</span></button>{sel===i&&<div style={{background:T.surface,padding:"13px 15px"}}><div style={{color:T.text,fontSize:13,lineHeight:1.65,marginBottom:13}}>{race.note}</div><div style={{display:"flex",gap:8}}><a href={race.frc} target="_blank" rel="noopener noreferrer" style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",background:T.card,border:`1px solid ${T.border}`,borderRadius:10,padding:"10px",color:T.text,fontSize:13,fontWeight:600,textDecoration:"none"}}>🏛️ FRC</a><a href={race.ins} target="_blank" rel="noopener noreferrer" style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",background:T.accent,border:"none",borderRadius:10,padding:"10px",color:"#fff",fontSize:13,fontWeight:700,textDecoration:"none"}}>✍️ Înscrie-te</a></div></div>}</div>)}</div></div>);}

