function makeDemoGPX(){return{name:"Antrenament Sibiu — Păltiniș",distance:52.3,ascent:847,descent:623,minEle:412,maxEle:1442,duration:142,avgSpeed:22.1,elevProfile:Array.from({length:20},(_,i)=>({dist:Math.round(52.3*i/20),ele:Math.round(412+Math.sin(i/20*Math.PI*4)*200+i*25)})),segments:[{from:0,to:5,g:0.8},{from:5,to:10,g:2.1},{from:10,to:16,g:5.4},{from:16,to:21,g:8.2},{from:21,to:26,g:6.7},{from:26,to:31,g:-3.2},{from:31,to:37,g:-5.8},{from:37,to:42,g:1.2},{from:42,to:47,g:2.4},{from:47,to:52,g:-1.1}]};}

function EChart({profile,ascent}){if(!profile?.length)return null;const eles=profile.map(p=>p.ele),minE=Math.min(...eles),maxE=Math.max(...eles),range=maxE-minE||1,W=300,H=70;const pts=profile.map((p,i)=>""+(i/(profile.length-1)*W)+","+(H-((p.ele-minE)/range)*(H-10)-5));return(<div style={{background:T.hi,borderRadius:12,padding:"11px 13px",marginBottom:13}}><div style={{color:T.muted,fontSize:11,fontWeight:700,textTransform:"uppercase",marginBottom:7}}>Profil elevație</div><svg width="100%" viewBox={"0 0 "+W+" "+H}><defs><linearGradient id="eg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={T.accent} stopOpacity="0.6"/><stop offset="100%" stopColor={T.accent} stopOpacity="0.05"/></linearGradient></defs><polygon points={"0,"+H+" "+pts.join(" ")+" "+W+","+H} fill="url(#eg)"/><polyline points={pts.join(" ")} fill="none" stroke={T.accent} strokeWidth="2" strokeLinejoin="round"/></svg><div style={{display:"flex",justifyContent:"space-between",marginTop:3}}><span style={{color:T.muted,fontSize:10}}>{minE}m</span><span style={{color:T.yellow,fontSize:10,fontWeight:700}}>↑ {ascent}m</span><span style={{color:T.muted,fontSize:10}}>{maxE}m</span></div></div>);}

function AnalysisPanel({gpx,user}){
  const[tab,setTab]=useState("zones");
  const segs=gpx.segments||[];
  const hard=segs.filter(s=>s.g>5),easy=segs.filter(s=>s.g>=0&&s.g<2);
  const total=segs.length||1;
  const z2p=Math.round(easy.length/total*100)||35;
  const z4p=Math.round(hard.length/total*80)||15;
  const z3p=Math.min(30,Math.round((total-hard.length-easy.length)/total*50))||25;
  const z1p=Math.max(0,100-z2p-z3p-z4p);
  const zones=[{z:1,l:"Z1 Recuperare",p:z1p,c:"#22c55e"},{z:2,l:"Z2 Anduranță",p:z2p,c:"#3b82f6"},{z:3,l:"Z3 Tempo",p:z3p,c:"#eab308"},{z:4,l:"Z4+ Prag/Max",p:z4p,c:"#ef4444"}];
  const critical=segs.filter(s=>s.g>4).sort((a,b)=>b.g-a.g).slice(0,3);
  const hrMax=user?.hrMax||185;
  const weight=user?.weight||75;
  const ftp=user?.ftp||220;
  const coef=user?.sex==="feminin"?0.068:0.075;
  const wkg=gpx.duration?((gpx.distance*weight*coef)/(gpx.duration/60)/weight).toFixed(1):null;
  const eff=wkg?(+wkg>3.5?"Excelentă":+wkg>2.8?"Bună":+wkg>2.0?"Medie":"În dezvoltare"):"N/A";
  const paceMin=gpx.duration&&gpx.distance>0?gpx.duration/gpx.distance:null;
  const tgt=user?.targetRace||"";
  let pred=null;
  if(paceMin){
    const isFlat=tgt.toLowerCase().includes("netindava")||tgt.toLowerCase().includes("slobozia")||tgt.toLowerCase().includes("bărăgan");
    const km=tgt?100:100;
    const predMin=Math.round(km*paceMin*(isFlat?0.85:1.0));
    pred={race:tgt||"Cursă de 100km",time:Math.floor(predMin/60)+"h "+String(predMin%60).padStart(2,"0")+"min",note:isFlat?"Teren plat — estimare ajustată cu +15% viteză față de tura ta.":"Estimare bazată pe ritmul mediu al turei tale."};
  }
  const tabs=[{k:"zones",l:"Zone HR",e:"❤️"},{k:"segs",l:"Segmente",e:"⛰️"},{k:"speed",l:"Viteză",e:"💨"},{k:"pred",l:"Predicție",e:"🎯"}];
  return(<div style={{marginBottom:14}}><div style={{color:T.white,fontWeight:800,fontSize:15,marginBottom:12}}>📊 Analiză detaliată</div><div style={{display:"flex",gap:5,marginBottom:14,overflowX:"auto",paddingBottom:2}}>{tabs.map(t=><button key={t.k} onClick={()=>setTab(t.k)} style={{flexShrink:0,padding:"6px 12px",borderRadius:20,border:`1px solid ${tab===t.k?T.accent:T.border}`,background:tab===t.k?T.accent:"transparent",color:tab===t.k?"#fff":T.muted,fontWeight:700,fontSize:11,cursor:"pointer"}}>{t.e} {t.l}</button>)}</div>
  {tab==="zones"&&<div style={{background:T.card,borderRadius:14,padding:"14px"}}><div style={{color:T.muted,fontSize:11,marginBottom:12,lineHeight:1.5}}>Distribuție estimată bazată pe gradienții traseului.</div>{zones.map((z,i)=><div key={i} style={{marginBottom:10}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{color:T.text,fontSize:12}}>{z.l}</span><span style={{color:z.c,fontWeight:700,fontSize:12}}>{z.p}%</span></div><div style={{background:T.border,borderRadius:4,height:8,overflow:"hidden"}}><div style={{width:z.p+"%",height:"100%",background:z.c,borderRadius:4}}/></div></div>)}<div style={{marginTop:12,padding:"10px 12px",background:T.hi,borderRadius:10}}><div style={{color:T.yellow,fontSize:11,fontWeight:700,marginBottom:4}}>💡 Interpretare</div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>{z2p>50?"Baza aerobă solidă — mult timp în Z2. Ideal pentru anduranță.":z4p>25?"Intensitate mare — asigură-te că recuperezi bine după această tură.":"Distribuție echilibrată. Continuă să lucrezi la baza aerobă."}</div></div></div>}
  {tab==="segs"&&<div style={{background:T.card,borderRadius:14,padding:"14px"}}>{critical.length>0?<><div style={{color:T.muted,fontSize:11,marginBottom:12}}>Top segmente solicitante ale traseului:</div>{critical.map((s,i)=><div key={i} style={{background:T.hi,borderRadius:12,padding:"12px 14px",marginBottom:8,borderLeft:`3px solid ${s.g>8?T.red:s.g>6?T.orange:T.yellow}`}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}><span style={{color:T.white,fontWeight:700,fontSize:13}}>km {s.from} — {s.to}</span><span style={{color:s.g>8?T.red:s.g>6?T.orange:T.yellow,fontWeight:800,fontSize:14}}>+{s.g}%</span></div><div style={{color:T.text,fontSize:12}}>{s.g>8?"🔴 Extrem — pedal în șezut, cadență mică":s.g>6?"🟠 Dificil — ritm constant, nu ataca":"🟡 Moderat — menține ritmul"}</div></div>)}<div style={{padding:"10px 12px",background:T.hi,borderRadius:10,marginTop:4}}><div style={{color:T.accent,fontSize:11,fontWeight:700,marginBottom:4}}>💡 Strategie urcări</div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>La gradiente peste 6%: cadență 65-75 rpm, HR sub {Math.round(hrMax*0.88)} bpm.</div></div></>:<div style={{textAlign:"center",padding:"20px 0",color:T.muted}}><div style={{fontSize:28,marginBottom:8}}>🟢</div><div>Traseu fără segmente critice. Teren relativ plat sau ușor.</div></div>}</div>}
  {tab==="speed"&&<div style={{background:T.card,borderRadius:14,padding:"14px"}}><div style={{color:T.muted,fontSize:11,marginBottom:12}}>Viteză estimată pe segmente:</div>{segs.map((s,i)=>{const spd=Math.max(8,Math.round((gpx.avgSpeed||22)-s.g*1.8));const pct=Math.round(spd/45*100);const c=spd>30?T.green:spd>22?T.accent:spd>15?T.yellow:T.orange;return(<div key={i} style={{marginBottom:8}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{color:T.text,fontSize:11}}>km {s.from}-{s.to} ({s.g>0?"+":""}{s.g}%)</span><span style={{color:c,fontWeight:700,fontSize:12}}>{spd} km/h</span></div><div style={{background:T.border,borderRadius:4,height:6,overflow:"hidden"}}><div style={{width:pct+"%",height:"100%",background:c,borderRadius:4}}/></div></div>);})}<div style={{marginTop:12,padding:"10px 12px",background:T.hi,borderRadius:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><div style={{color:T.muted,fontSize:11}}>Eficiență pedalare</div><div style={{color:T.white,fontWeight:700,fontSize:14}}>{eff}</div></div>{wkg&&<div style={{textAlign:"right"}}><div style={{color:T.muted,fontSize:11}}>W/kg estimat</div><div style={{color:T.yellow,fontWeight:800,fontSize:20}}>{wkg}</div></div>}</div></div>}
  {tab==="pred"&&<div style={{background:T.card,borderRadius:14,padding:"14px"}}>{pred?<><div style={{textAlign:"center",marginBottom:16}}><div style={{fontSize:30,marginBottom:8}}>🎯</div><div style={{color:T.muted,fontSize:12,marginBottom:4}}>Predicție timp pentru</div><div style={{color:T.white,fontWeight:800,fontSize:15}}>{pred.race}</div></div><div style={{background:`linear-gradient(135deg,${T.dim},#1a1e2a)`,borderRadius:14,padding:"20px",textAlign:"center",marginBottom:14,border:`1px solid ${T.accent}44`}}><div style={{color:T.muted,fontSize:11,textTransform:"uppercase",letterSpacing:"0.1em",marginBottom:6}}>Timp estimat</div><div style={{color:T.accent,fontWeight:900,fontSize:34}}>{pred.time}</div></div><div style={{padding:"10px 12px",background:T.hi,borderRadius:10,marginBottom:10}}><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>{pred.note}</div></div><div style={{padding:"10px 12px",background:T.hi,borderRadius:10}}><div style={{color:T.yellow,fontSize:11,fontWeight:700,marginBottom:4}}>📈 Cum să îmbunătățești</div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>Fiecare 10% creștere FTP reduce timpul cu ~5-7%. Tintește {Math.round(ftp*1.1)}W față de actualul {ftp}W.</div></div></>:<div style={{textAlign:"center",padding:"20px 0"}}><div style={{fontSize:28,marginBottom:8}}>⚠️</div><div style={{color:T.muted,fontSize:13,marginBottom:8}}>Setează o cursă țintă în profil pentru predicție precisă.</div></div>}</div>}
  </div>);}

function makePlan(user,gpx){const f=user?.sex==="feminin",h=gpx.ascent>500,hrMax=user?.hrMax||185,w=user?.weight||75,ftp=user?.ftp||220,tgt=user?.targetRace||"cursele viitoare",coef=f?0.068:0.075,kcal=Math.round(gpx.distance*w*coef),gels=Math.ceil(gpx.distance/25)-1,z2lo=Math.round(hrMax*0.65),z2hi=Math.round(hrMax*0.70),tempo=Math.round(hrMax*0.84),max92=Math.round(hrMax*0.92),r1=f?"2h":"2h 30min",r2=f?"2h 30min":"3h",r3=f?"3h":"3h 30min";return{analysis:"Traseu de "+gpx.distance+"km cu "+gpx.ascent+"m urcare — profil "+(h?"montan solicitant":"moderat")+". Plan adaptat pentru "+tgt+(f?" (ajustat pentru femei)":"")+".",strengths:["Capacitate aerobă în dezvoltare",h?"Experiență pe urcări":"Viteză pe plat"],improvements:[h?"Forță specifică urcări":"Rezistență efort prelungit","Managementul efortului"],weeks:[{wk:1,focus:"Baza aerobă",ses:[{d:"Luni",t:"Recuperare",dur:"45 min",desc:"Zona 1-2, HR sub "+z2lo+" bpm."},{d:"Miercuri",t:"Zona 2",dur:"90 min",desc:"HR "+z2lo+"-"+z2hi+" bpm. Cadență 80-85 rpm."},{d:"Vineri",t:"Intervale",dur:"60 min",desc:"4x8 min Sweet Spot (88-93% FTP). Rec. 4 min."},{d:"Duminică",t:"Tura lunga",dur:r1,desc:"Gel la fiecare 45 min."}]},{wk:2,focus:"Cresc intensitatea",ses:[{d:"Luni",t:"Recuperare",dur:"45 min",desc:"Recuperare activă."},{d:"Miercuri",t:"Tempo",dur:"75 min",desc:"20 min Tempo la "+tempo+" bpm."},{d:"Vineri",t:"Intervale",dur:"60 min",desc:"5x5 min VO2max. Rec. 5 min."},{d:"Duminică",t:"Tura lunga",dur:r2,desc:h?"Include 2-3 urcări la Zona 3-4.":"Teren plat, ritm constant."}]},{wk:3,focus:"Simulare cursă",ses:[{d:"Luni",t:"Recuperare",dur:"45 min",desc:"Recuperare activă."},{d:"Miercuri",t:"Sweet Spot",dur:"90 min",desc:"3x15 min Sweet Spot."},{d:"Vineri",t:"Zona 2",dur:"60 min",desc:"Activare ușoară."},{d:"Duminică",t:"Tura lunga",dur:r3,desc:"Simulare cursă. ~"+gels+" geluri."}]},{wk:4,focus:"Recuperare & formă maximă",ses:[{d:"Luni",t:"Odihna",dur:"—",desc:"Odihnă completă."},{d:"Miercuri",t:"Zona 2",dur:"60 min",desc:"Tură ușoară."},{d:"Vineri",t:"Recuperare",dur:"30 min",desc:"Activare 4x30s."},{d:"Duminică",t:"Cursa",dur:"—",desc:"Ai încredere în antrenamentele făcute!"}]}],nutr:"La "+w+"kg și "+gpx.distance+"km: ~"+kcal+" kcal. Gel la km 30, 55"+(gpx.distance>80?", 80":"")+".",race:user?.targetRace?"Pentru "+tgt+": pornește conservator. HR max "+max92+" bpm în primele 20 min.":null};}
const SC={"Recuperare":T.green,"Zona 2":T.accent,"Intervale":T.red,"Tura lunga":T.yellow,"Sweet Spot":T.orange,"Tempo":T.uci,"Odihna":T.muted,"Cursa":T.red};

function AITab({user}){
  const[stage,setStage]=useState("up");const[gpx,setGpx]=useState(null);const[ow,setOw]=useState(0);const fileRef=useRef();
  const reset=()=>{setStage("up");setGpx(null);};
  const loadDemo=()=>{setStage("an");setTimeout(()=>{setGpx(makeDemoGPX());setStage("done");},800);};
  const loadFile=file=>{setStage("an");const reader=new FileReader();reader.onload=e=>{try{const doc=new DOMParser().parseFromString(e.target.result,"text/xml");const trkpts=Array.from(doc.querySelectorAll("trkpt"));if(!trkpts.length){setGpx(makeDemoGPX());setStage("done");return;}const points=trkpts.map(pt=>({lat:parseFloat(pt.getAttribute("lat")),lon:parseFloat(pt.getAttribute("lon")),ele:parseFloat(pt.querySelector("ele")?.textContent||0),time:pt.querySelector("time")?.textContent||null}));let totalDist=0;for(let i=1;i<points.length;i++){const p1=points[i-1],p2=points[i],dLat=(p2.lat-p1.lat)*Math.PI/180,dLon=(p2.lon-p1.lon)*Math.PI/180,a=Math.sin(dLat/2)**2+Math.cos(p1.lat*Math.PI/180)*Math.cos(p2.lat*Math.PI/180)*Math.sin(dLon/2)**2;totalDist+=6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}let ascent=0,descent=0;for(let i=1;i<points.length;i++){const d=points[i].ele-points[i-1].ele;if(d>0)ascent+=d;else descent+=Math.abs(d);}const eles=points.map(p=>p.ele),minEle=Math.min(...eles),maxEle=Math.max(...eles);let duration=null;if(points[0].time&&points[points.length-1].time)duration=Math.round((new Date(points[points.length-1].time)-new Date(points[0].time))/60000);const step=Math.max(1,Math.floor(points.length/20));const elevProfile=points.filter((_,i)=>i%step===0).slice(0,20).map((p,i,arr)=>({dist:Math.round(totalDist/1000*i/arr.length),ele:Math.round(p.ele)}));const segSize=Math.max(1,Math.floor(points.length/10));const segments=Array.from({length:10},(_,s)=>{const seg=points.slice(s*segSize,(s+1)*segSize);if(seg.length<2)return null;let sd=0;for(let i=1;i<seg.length;i++){const p1=seg[i-1],p2=seg[i],dLat=(p2.lat-p1.lat)*Math.PI/180,dLon=(p2.lon-p1.lon)*Math.PI/180,a=Math.sin(dLat/2)**2+Math.cos(p1.lat*Math.PI/180)*Math.cos(p2.lat*Math.PI/180)*Math.sin(dLon/2)**2;sd+=6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}return{from:Math.round(totalDist/1000*s/10),to:Math.round(totalDist/1000*(s+1)/10),g:sd>0?Math.round((seg[seg.length-1].ele-seg[0].ele)/sd*1000)/10:0};}).filter(Boolean);const distance=Math.round(totalDist/100)/10;const name=doc.querySelector("name")?.textContent||doc.querySelector("trk > name")?.textContent||file.name.replace(".gpx","");setGpx({name,distance,ascent:Math.round(ascent),descent:Math.round(descent),minEle:Math.round(minEle),maxEle:Math.round(maxEle),duration,avgSpeed:duration?Math.round(distance/(duration/60)*10)/10:null,elevProfile,segments});setStage("done");}catch(err){setGpx(makeDemoGPX());setStage("done");}};reader.readAsText(file);};
  const plan=gpx?makePlan(user,gpx):null;
  if(stage==="up")return(<div><div style={{textAlign:"center",marginBottom:18}}><div style={{fontSize:38,marginBottom:8}}>🤖</div><div style={{color:T.white,fontWeight:800,fontSize:17,marginBottom:5}}>Plan AI Personalizat{user?.sex==="feminin"?" ♀":""}</div><div style={{color:T.muted,fontSize:13,lineHeight:1.6}}>Încarcă un fișier GPX și primești analiză detaliată + plan de antrenament.</div></div><input ref={fileRef} type="file" accept=".gpx" style={{display:"none"}} onChange={e=>{if(e.target.files[0])loadFile(e.target.files[0]);}}/><button onClick={()=>fileRef.current.click()} style={{width:"100%",background:T.dim,border:`2px dashed ${T.accent}`,borderRadius:14,padding:"20px",cursor:"pointer",marginBottom:10}}><div style={{fontSize:26,marginBottom:5}}>📂</div><div style={{color:T.white,fontWeight:700,fontSize:14,marginBottom:2}}>Alege fișier GPX</div><div style={{color:T.muted,fontSize:12}}>Garmin Connect, Geoid CC700 Pro, Strava</div></button><button onClick={loadDemo} style={{width:"100%",background:T.card,border:`1px solid ${T.border}`,borderRadius:13,padding:"12px",cursor:"pointer"}}><span style={{color:T.muted,fontSize:13}}>🔄 Demo: Sibiu — Păltiniș (52km, 847m)</span></button></div>);
  if(stage==="an")return(<div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:260}}><style>{`@keyframes spin{from{transform:rotate(0)}to{transform:rotate(360deg)}}`}</style><div style={{fontSize:34,marginBottom:12,animation:"spin 1s linear infinite"}}>⚙️</div><div style={{color:T.white,fontWeight:700}}>Analizez traseul...</div></div>);
  if(stage==="done"&&gpx&&!plan){
    const segs = gpx.segments||[];
    const hard = segs.filter(s=>s.g>5).sort((a,b)=>b.g-a.g).slice(0,3);
    return (
      <div>
        {/* Header */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14}}>
          <div>
            <div style={{color:T.white,fontWeight:800,fontSize:15}}>{gpx.name}</div>
            <div style={{color:T.green,fontSize:11,marginTop:2}}>✓ Analizat cu succes</div>
          </div>
          <button onClick={reset} style={{background:"none",border:`1px solid ${T.border}`,borderRadius:8,padding:"5px 10px",color:T.muted,fontSize:12,cursor:"pointer"}}>× Schimbă</button>
        </div>

        {/* Stats */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:9,marginBottom:14}}>
          <Pill icon="📏" value={gpx.distance+"km"} label="distanță" color={T.accent}/>
          <Pill icon="⛰️" value={gpx.ascent+"m"} label="urcare totală" color={T.yellow}/>
          <Pill icon="⏱️" value={gpx.duration?gpx.duration+"min":"N/A"} label="durată" color={T.uci}/>
          <Pill icon="💨" value={gpx.avgSpeed?gpx.avgSpeed+"km/h":"N/A"} label="viteză medie" color={T.green}/>
        </div>

        {/* Elevation chart */}
        <EChart profile={gpx.elevProfile} ascent={gpx.ascent}/>

        {/* Hard segments */}
        {hard.length > 0 && (
          <div style={{background:T.card,borderRadius:12,padding:"12px 14px",marginBottom:14}}>
            <div style={{color:T.orange,fontSize:11,fontWeight:700,textTransform:"uppercase",marginBottom:10}}>⛰️ Segmente dificile</div>
            {hard.map((s,i) => (
              <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"7px 0",borderBottom:i<hard.length-1?`1px solid ${T.border}`:"none"}}>
                <span style={{color:T.text,fontSize:13}}>km {s.from} — {s.to}</span>
                <span style={{color:s.g>8?T.red:s.g>6?T.orange:T.yellow,fontWeight:800,fontSize:14}}>+{s.g}%</span>
              </div>
            ))}
          </div>
        )}

        {/* CTA */}
        <Btn onClick={()=>setStage("plan")}>🤖 Generează Plan AI 4 Săptămâni</Btn>
      </div>
    );
  }
  if(plan)return(<div><div style={{background:`linear-gradient(135deg,${T.dim},#1a1e2a)`,borderRadius:14,padding:"13px",marginBottom:11,border:`1px solid ${T.accent}44`}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:5}}><div><div style={{color:T.accent,fontSize:10,fontWeight:700,textTransform:"uppercase"}}>Plan AI{user?.sex==="feminin"?" ♀":""}</div><div style={{color:T.white,fontWeight:800,fontSize:14,marginTop:2}}>{gpx.name}</div></div><button onClick={reset} style={{background:"none",border:`1px solid ${T.border}`,borderRadius:7,padding:"3px 8px",color:T.muted,fontSize:11,cursor:"pointer"}}>↺</button></div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>{plan.analysis}</div></div><div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:9,marginBottom:11}}><Card style={{padding:"11px 12px"}}><div style={{color:T.green,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:5}}>💪 Puncte forte</div>{plan.strengths.map((s,i)=><div key={i} style={{color:T.text,fontSize:12,marginBottom:3}}>• {s}</div>)}</Card><Card style={{padding:"11px 12px"}}><div style={{color:T.orange,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:5}}>🎯 De lucrat</div>{plan.improvements.map((s,i)=><div key={i} style={{color:T.text,fontSize:12,marginBottom:3}}>• {s}</div>)}</Card></div>{plan.weeks.map((wk,wi)=><div key={wi} style={{borderRadius:13,overflow:"hidden",border:`1px solid ${ow===wi?T.accent+"55":T.border}`,marginBottom:7}}><button onClick={()=>setOw(ow===wi?-1:wi)} style={{width:"100%",background:ow===wi?T.hi:T.card,border:"none",padding:"11px 14px",cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center"}}><div style={{textAlign:"left"}}><div style={{color:T.muted,fontSize:10,fontWeight:700,textTransform:"uppercase"}}>Săptămâna {wk.wk}</div><div style={{color:T.white,fontWeight:700,fontSize:13,marginTop:1}}>{wk.focus}</div></div><span style={{color:T.accent,fontSize:14,transform:ow===wi?"rotate(180deg)":"none",transition:"transform .2s"}}>⌄</span></button>{ow===wi&&<div style={{background:T.surface,padding:"9px 11px",display:"flex",flexDirection:"column",gap:7}}>{wk.ses.map((s,si)=>{const c=SC[s.t]||T.accent;return(<div key={si} style={{background:T.card,borderRadius:11,padding:"9px 12px",borderLeft:`3px solid ${c}`}}><div style={{display:"flex",justifyContent:"space-between",marginBottom:3}}><span style={{color:T.muted,fontSize:11,fontWeight:700}}>{s.d}</span><div style={{display:"flex",gap:5,alignItems:"center"}}><Badge label={s.t} color={c}/><span style={{color:T.muted,fontSize:10}}>{s.dur}</span></div></div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>{s.desc}</div></div>);})}</div>}</div>)}{plan.nutr&&<Card style={{padding:"11px 13px",marginTop:4,marginBottom:7,borderLeft:`3px solid ${T.yellow}`}}><div style={{color:T.yellow,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:4}}>🍌 Nutriție</div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>{plan.nutr}</div></Card>}{plan.race&&<Card style={{padding:"11px 13px",borderLeft:`3px solid ${T.red}`}}><div style={{color:T.red,fontSize:10,fontWeight:700,textTransform:"uppercase",marginBottom:4}}>🏁 Cursa țintă</div><div style={{color:T.text,fontSize:12,lineHeight:1.6}}>{plan.race}</div></Card>}</div>);
  return null;}

// AUTH
const STEPS=[{title:"Cont nou",sub:"Date de autentificare"},{title:"Profilul tău",sub:"Date personale"},{title:"Date ciclism",sub:"Nivel și obiective"}];
function Splash({onLogin,onReg,onAuto}){useEffect(()=>{const s=loadU();if(s)setTimeout(()=>onAuto(s),300);},[]);const v=useAnim("sp");return(<div style={{minHeight:"100vh",background:T.bg,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:24,opacity:v?1:0,transition:"opacity .4s"}}><Logo s={72}/><div style={{textAlign:"center",margin:"16px 0 8px"}}><div style={{display:"flex",alignItems:"baseline",justifyContent:"center",gap:8}}><span style={{color:T.white,fontWeight:900,fontSize:26,letterSpacing:"-.5px"}}>CYCLING</span><span style={{color:T.accent,fontWeight:300,fontSize:26,letterSpacing:"4px"}}>COMPANION</span></div><div style={{display:"flex",gap:2,justifyContent:"center",marginTop:6}}><div style={{height:3,width:36,background:T.ro1,borderRadius:2}}/><div style={{height:3,width:36,background:T.ro2,borderRadius:2}}/><div style={{height:3,width:36,background:T.ro3,borderRadius:2}}/></div></div><div style={{color:T.muted,fontSize:13,textAlign:"center",marginBottom:30,lineHeight:1.6}}>Platforma cicliștilor români.<br/>Antrenamente. Curse. Comunitate.</div><div style={{display:"flex",gap:7,flexWrap:"wrap",justifyContent:"center",marginBottom:30}}>{["🤖 Plan AI","📊 Analiză GPX","🛒 Produse","♀️ Feminin","🏁 FRC"].map((f,i)=><div key={i} style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:20,padding:"5px 12px",color:T.text,fontSize:11}}>{f}</div>)}</div><div style={{width:"100%",maxWidth:380,display:"flex",flexDirection:"column",gap:11}}><Btn onClick={onReg}>Creează cont gratuit</Btn><Btn variant="ghost" onClick={onLogin}>Am deja cont — Intră</Btn></div></div>);}
function Login({onLogin,onBack,onReg,onForgot}){const[email,setEmail]=useState("");const[pass,setPass]=useState("");const[sp,setSp]=useState(false);const[rem,setRem]=useState(true);const[err,setErr]=useState("");const go=()=>{if(!email.includes("@")){setErr("Email invalid.");return;}if(pass.length<4){setErr("Parolă prea scurtă.");return;}const u={name:email.split("@")[0],email,level:"intermediar",weight:75,age:30,hrMax:185,ftp:220,sex:"masculin",bikeType:"sosea",goal:"",targetRace:"Netindava 25 iulie",city:"Sibiu"};if(rem)saveU(u);onLogin(u);};return(<div style={{minHeight:"100vh",background:T.bg,display:"flex",flexDirection:"column",padding:24}}><button onClick={onBack} style={{background:"none",border:"none",color:T.muted,fontSize:13,cursor:"pointer",textAlign:"left",marginBottom:28,padding:0}}>← Înapoi</button><div style={{display:"flex",alignItems:"center",gap:12,marginBottom:28}}><Logo s={36}/><div><div style={{color:T.white,fontWeight:900,fontSize:19}}>Bun venit înapoi!</div><div style={{color:T.muted,fontSize:12}}>Intră în contul tău</div></div></div><Inp label="Email" type="email" value={email} onChange={setEmail} placeholder="email@exemplu.ro" icon="✉️"/><Inp label="Parolă" type={sp?"text":"password"} value={pass} onChange={setPass} placeholder="••••••••" icon="🔒" right={<button onClick={()=>setSp(!sp)} style={{background:"none",border:"none",color:T.muted,cursor:"pointer",fontSize:15,padding:0}}>{sp?"🙈":"👁️"}</button>}/><Chk label="Ține minte contul" sub="Rămâi autentificat la vizita următoare" checked={rem} onChange={setRem}/>{err&&<div style={{color:T.red,fontSize:13,margin:"10px 0",padding:"9px 13px",background:T.red+"11",borderRadius:10}}>⚠️ {err}</div>}<div style={{marginTop:10,marginBottom:14}}><Btn onClick={go} disabled={!email||!pass}>Intră în cont</Btn></div><button onClick={onForgot} style={{background:"none",border:"none",color:T.accent,fontSize:13,cursor:"pointer",textAlign:"center",marginBottom:14}}>Ai uitat parola?</button><div style={{color:T.muted,fontSize:13,textAlign:"center"}}>Nu ai cont?{" "}<button onClick={onReg} style={{background:"none",border:"none",color:T.accent,fontWeight:700,cursor:"pointer",fontSize:13}}>Înregistrează-te</button></div></div>);}
function Forgot({onBack}){const[email,setEmail]=useState("");const[sent,setSent]=useState(false);return(<div style={{minHeight:"100vh",background:T.bg,display:"flex",flexDirection:"column",padding:24}}><button onClick={onBack} style={{background:"none",border:"none",color:T.muted,fontSize:13,cursor:"pointer",textAlign:"left",marginBottom:28,padding:0}}>← Înapoi</button><div style={{display:"flex",alignItems:"center",gap:12,marginBottom:28}}><div style={{width:46,height:46,borderRadius:13,background:T.dim,border:`1px solid ${T.accent}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}>🔑</div><div><div style={{color:T.white,fontWeight:900,fontSize:19}}>Recuperare parolă</div><div style={{color:T.muted,fontSize:12}}>Îți trimitem un link pe email</div></div></div>{!sent?<><div style={{color:T.text,fontSize:14,lineHeight:1.6,marginBottom:20}}>Introdu adresa de email cu care te-ai înregistrat.</div><Inp label="Email" type="email" value={email} onChange={setEmail} placeholder="email@exemplu.ro" icon="✉️"/><Btn onClick={()=>setSent(true)} disabled={!email.includes("@")}>Trimite link de resetare</Btn></>:<div style={{textAlign:"center",paddingTop:20}}><div style={{fontSize:50,marginBottom:14}}>📧</div><div style={{color:T.white,fontWeight:800,fontSize:18,marginBottom:8}}>Email trimis!</div><div style={{color:T.accent,fontWeight:700,fontSize:15,marginBottom:18}}>{email}</div><div style={{color:T.muted,fontSize:13,lineHeight:1.6,marginBottom:22}}>Verifică și Spam. Link-ul expiră în 30 minute.</div><Btn variant="ghost" onClick={onBack}>← Înapoi la login</Btn></div>}</div>);}
function Register({onReg,onBack,onLogin}){const[step,setStep]=useState(0);const[form,setForm]=useState({name:"",email:"",pass:"",pass2:"",avatar:null,sex:"masculin",age:30,weight:75,city:"",bikeType:"sosea",level:"intermediar",hrMax:185,ftp:220,goal:"",targetRace:""});const[err,setErr]=useState("");const[sp,setSp]=useState(false);const v=useAnim(step);const set=(k,val)=>setForm(f=>({...f,[k]:val}));useEffect(()=>{set("hrMax",form.sex==="feminin"?226-form.age:220-form.age);},[form.sex,form.age]);const validate=()=>{if(step===0){if(!form.name.trim())return"Introdu numele.";if(!form.email.includes("@"))return"Email invalid.";if(form.pass.length<6)return"Parolă min 6 caractere.";if(form.pass!==form.pass2)return"Parolele nu coincid.";}if(step===1&&!form.city.trim())return"Introdu orașul.";return"";};const next=()=>{const e=validate();if(e){setErr(e);return;}setErr("");if(step<2)setStep(s=>s+1);else onReg(form);};return(<div style={{minHeight:"100vh",background:T.bg,display:"flex",flexDirection:"column",padding:24}}><button onClick={step===0?onBack:()=>{setStep(s=>s-1);setErr("");}} style={{background:"none",border:"none",color:T.muted,fontSize:13,cursor:"pointer",textAlign:"left",marginBottom:18,padding:0}}>← Înapoi</button><div style={{display:"flex",gap:6,marginBottom:20}}>{STEPS.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:2,background:i<=step?T.accent:T.border,transition:"background .3s"}}/>)}</div><div style={{marginBottom:20,opacity:v?1:0,transition:"opacity .3s"}}><div style={{color:T.muted,fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.1em",marginBottom:3}}>Pas {step+1} din 3</div><div style={{color:T.white,fontWeight:900,fontSize:21}}>{STEPS[step].title}</div><div style={{color:T.muted,fontSize:13}}>{STEPS[step].sub}</div></div><div style={{flex:1}}>{step===0&&<><AvatarPic value={form.avatar} onChange={v=>set("avatar",v)} name={form.name}/><Inp label="Nume complet" value={form.name} onChange={v=>set("name",v)} placeholder="Ion Popescu" icon="👤"/><Inp label="Email" type="email" value={form.email} onChange={v=>set("email",v)} placeholder="email@exemplu.ro" icon="✉️"/><Inp label="Parolă" type={sp?"text":"password"} value={form.pass} onChange={v=>set("pass",v)} placeholder="minim 6 caractere" icon="🔒" right={<button onClick={()=>setSp(!sp)} style={{background:"none",border:"none",color:T.muted,cursor:"pointer",fontSize:15,padding:0}}>{sp?"🙈":"👁️"}</button>}/><Inp label="Confirmă parola" type="password" value={form.pass2} onChange={v=>set("pass2",v)} placeholder="repetă parola" icon="🔒"/></>}{step===1&&<><Toggle label="Sex" value={form.sex} onChange={v=>set("sex",v)} options={SEXO}/><div style={{display:"flex",gap:12}}><div style={{flex:1}}><NInput label="Vârstă" value={form.age} onChange={v=>set("age",v)} min={15} max={80} unit="ani"/></div><div style={{flex:1}}><NInput label="Greutate" value={form.weight} onChange={v=>set("weight",v)} min={40} max={150} unit="kg"/></div></div><Inp label="Oraș" value={form.city} onChange={v=>set("city",v)} placeholder="ex: Sibiu" icon="📍"/><div style={{background:T.hi,borderRadius:11,padding:"10px 13px",marginBottom:14,border:`1px solid ${T.border}`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><div style={{color:T.muted,fontSize:11,fontWeight:700,textTransform:"uppercase"}}>HR Max estimat</div><div style={{color:T.muted,fontSize:11,marginTop:1}}>{form.sex==="feminin"?"226":"220"} - {form.age} ani{form.sex==="feminin"&&<span style={{color:T.pink,marginLeft:5}}>♀</span>}</div></div><div style={{color:T.red,fontWeight:900,fontSize:20}}>{form.hrMax} <span style={{fontSize:12,fontWeight:400}}>bpm</span></div></div></div></>}{step===2&&<><Toggle label="Tip bicicletă" value={form.bikeType} onChange={v=>set("bikeType",v)} options={BIKEO}/><Sel label="Nivel" value={form.level} onChange={v=>set("level",v)} options={[{v:"incepator",l:"🟢 Începător"},{v:"intermediar",l:"🟡 Intermediar"},{v:"avansat",l:"🔴 Avansat"}]}/><div style={{display:"flex",gap:12}}><div style={{flex:1}}><NInput label="HR Max real" value={form.hrMax} onChange={v=>set("hrMax",v)} min={140} max={230} unit="bpm"/></div><div style={{flex:1}}><NInput label="FTP" value={form.ftp} onChange={v=>set("ftp",v)} min={100} max={500} unit="W"/></div></div><Sel label="Obiectiv" value={form.goal} onChange={v=>set("goal",v)} options={[{v:"",l:"Alege..."},{v:"prima_cursa",l:"🏁 Prima cursă"},{v:"timp",l:"⏱️ Îmbunătățesc timpul"},{v:"anduranta",l:"💪 Cresc anduranța"},{v:"podium",l:"🏆 Podium amatori"}]}/><Inp label="Cursa țintă" value={form.targetRace} onChange={v=>set("targetRace",v)} placeholder="ex: Netindava 25 iulie" icon="🎯"/></>}</div>{err&&<div style={{color:T.red,fontSize:13,margin:"10px 0",padding:"9px 13px",background:T.red+"11",borderRadius:10}}>⚠️ {err}</div>}<div style={{marginTop:14}}><Btn onClick={next}>{step<2?"Continuă →":"🚀 Creează contul"}</Btn>{step===0&&<div style={{color:T.muted,fontSize:13,textAlign:"center",marginTop:12}}>Ai deja cont?{" "}<button onClick={onLogin} style={{background:"none",border:"none",color:T.accent,fontWeight:700,cursor:"pointer",fontSize:13}}>Intră</button></div>}</div></div>);}

// EDIT + PROFILE
function EditProfile({user,onSave,onBack}){const[form,setForm]=useState({...user});const set=(k,v)=>setForm(f=>({...f,[k]:v}));useEffect(()=>{set("hrMax",form.sex==="feminin"?226-form.age:220-form.age);},[form.sex,form.age]);return(<div><div style={{display:"flex",alignItems:"center",gap:10,marginBottom:24}}><button onClick={onBack} style={{background:"none",border:"none",color:T.muted,fontSize:13,cursor:"pointer",padding:0}}>← Înapoi</button><div style={{color:T.white,fontWeight:800,fontSize:18}}>Editează profilul</div></div><AvatarPic value={form.avatar} onChange={v=>set("avatar",v)} name={form.name}/><Inp label="Nume" value={form.name} onChange={v=>set("name",v)} placeholder="Numele tău" icon="👤"/><Inp label="Email" type="email" value={form.email} onChange={v=>set("email",v)} placeholder="email@exemplu.ro" icon="✉️"/><Inp label="Oraș" value={form.city} onChange={v=>set("city",v)} placeholder="ex: Sibiu" icon="📍"/><Toggle label="Sex" value={form.sex} onChange={v=>set("sex",v)} options={SEXO}/><div style={{display:"flex",gap:12,marginBottom:4}}><div style={{flex:1}}><NInput label="Vârstă" value={form.age} onChange={v=>set("age",v)} min={15} max={80} unit="ani"/></div><div style={{flex:1}}><NInput label="Greutate" value={form.weight} onChange={v=>set("weight",v)} min={40} max={150} unit="kg"/></div></div><Toggle label="Tip bicicletă" value={form.bikeType} onChange={v=>set("bikeType",v)} options={BIKEO}/><div style={{display:"flex",gap:12,marginBottom:4}}><div style={{flex:1}}><NInput label="HR Max" value={form.hrMax} onChange={v=>set("hrMax",v)} min={140} max={230} unit="bpm"/></div><div style={{flex:1}}><NInput label="FTP" value={form.ftp} onChange={v=>set("ftp",v)} min={100} max={500} unit="W"/></div></div><Inp label="Cursa țintă" value={form.targetRace} onChange={v=>set("targetRace",v)} placeholder="ex: Netindava 25 iulie" icon="🎯"/><div style={{marginTop:8}}><Btn onClick={()=>onSave(form)}>💾 Salvează modificările</Btn></div></div>);}
function ProfileTab({user,onLogout,onAvatar,onUpdate}){const[editing,setEditing]=useState(false);const lc={incepator:T.green,intermediar:T.yellow,avansat:T.red};const bl=BIKEO.find(b=>b.v===user.bikeType)?.l||"Șosea";const bi=BIKEO.find(b=>b.v===user.bikeType)?.i||"🚴";if(editing)return <EditProfile user={user} onSave={u=>{onUpdate(u);setEditing(false);}} onBack={()=>setEditing(false)}/>;return(<div><div style={{display:"flex",alignItems:"center",gap:14,marginBottom:18,padding:"14px",background:T.card,borderRadius:14,border:`1px solid ${T.border}`}}><AvatarPic value={user.avatar} onChange={onAvatar} name={user.name} size={56}/><div style={{flex:1}}><div style={{color:T.white,fontWeight:800,fontSize:17}}>{user.name}</div><div style={{color:T.muted,fontSize:12,marginBottom:6}}>{user.email}</div><div style={{display:"flex",gap:5,flexWrap:"wrap"}}><Badge label={user.level||"intermediar"} color={lc[user.level]||T.accent}/><Badge label={user.sex==="feminin"?"♀ Feminin":"♂ Masculin"} color={user.sex==="feminin"?T.pink:T.accent}/><Badge label={bi+" "+bl} color={T.orange}/></div></div><button onClick={()=>setEditing(true)} style={{background:T.hi,border:`1px solid ${T.border}`,borderRadius:10,padding:"8px 12px",color:T.text,fontSize:12,fontWeight:600,cursor:"pointer",flexShrink:0}}>✏️ Editează</button></div><div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:9,marginBottom:16}}><Pill icon="❤️" value={user.hrMax||185} label="HR Max" color={T.red}/><Pill icon="⚡" value={(user.ftp||220)+"W"} label="FTP" color={T.yellow}/><Pill icon="⚖️" value={(user.weight||75)+"kg"} label="Greutate" color={T.accent}/></div><Card style={{padding:"14px",marginBottom:12}}><div style={{color:T.accent,fontSize:11,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Date personale</div>{[{i:"📍",l:"Oraș",v:user.city||"—"},{i:"🎂",l:"Vârstă",v:user.age?user.age+" ani":"—"},{i:bi,l:"Bicicletă",v:bl},{i:"🏁",l:"Cursa țintă",v:user.targetRace||"—"}].map((r,i,arr)=><div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:i<arr.length-1?`1px solid ${T.border}`:"none"}}><span style={{color:T.muted,fontSize:13}}>{r.i} {r.l}</span><span style={{color:T.white,fontSize:13,fontWeight:600}}>{r.v}</span></div>)}</Card>{user.sex==="feminin"&&<FemSec title="Echipament pentru femei" tips={FEM.equip}/>}<button onClick={onLogout} style={{width:"100%",background:"none",border:`1px solid ${T.border}`,borderRadius:13,padding:"13px",color:T.muted,fontSize:14,fontWeight:600,cursor:"pointer",marginTop:14}}>Ieși din cont</button></div>);}

// APP
const NAV_OUT=[{i:"📡",l:"Știri"},{i:"🛒",l:"Produse"},{i:"🍌",l:"Nutriție"},{i:"❤️",l:"HR"},{i:"🏁",l:"Curse"}];
const NAV_IN=[{i:"📡",l:"Știri"},{i:"🤖",l:"Plan AI"},{i:"🛒",l:"Produse"},{i:"🍌",l:"Nutriție"},{i:"❤️",l:"HR"},{i:"🏁",l:"Curse"},{i:"👤",l:"Profil"}];
const SUBS={"📡":"Știri live • Curse • Transferuri","🤖":"Upload GPX • Analiză • Plan personalizat","🛒":"Echipament recomandat • Toate bugetele","🍌":"Ce mănânci înainte, în cursă și după","❤️":"Antrenează-te inteligent","🏁":"Curse de șosea — sursă: FRC","👤":"Contul tău"};
export default function App(){
  const[screen,setScreen]=useState("sp");const[user,setUser]=useState(null);const[tab,setTab]=useState(0);const visible=useAnim(tab);
  const login=u=>{setUser(u);setScreen("app");setTab(0);};
  const logout=()=>{clearU();setUser(null);setScreen("sp");setTab(0);};
  const updateUser=u=>{setUser(u);saveU(u);};
  if(screen==="sp")return <Splash onLogin={()=>setScreen("lg")} onReg={()=>setScreen("rg")} onAuto={login}/>;
  if(screen==="lg")return <Login onLogin={login} onBack={()=>setScreen("sp")} onReg={()=>setScreen("rg")} onForgot={()=>setScreen("fg")}/>;
  if(screen==="fg")return <Forgot onBack={()=>setScreen("lg")}/>;
  if(screen==="rg")return <Register onReg={login} onBack={()=>setScreen("sp")} onLogin={()=>setScreen("lg")}/>;
  const nav=user?NAV_IN:NAV_OUT;const ci=nav[tab]?.i||"📡";
  const screens=user?[<NewsTab/>,<GPXAnalyzer user={user} T={T}/>,<ProductsTab user={user}/>,<NutrTab user={user}/>,<HRTab user={user}/>,<CalTab/>,<ProfileTab user={user} onLogout={logout} onAvatar={av=>updateUser({...user,avatar:av})} onUpdate={updateUser}/>]:[<NewsTab/>,<ProductsTab/>,<NutrTab/>,<HRTab/>,<CalTab/>];
  return(<div style={{background:T.bg,minHeight:"100vh",maxWidth:480,margin:"0 auto",fontFamily:"'Inter',system-ui,sans-serif",color:T.white,display:"flex",flexDirection:"column"}}><div style={{background:T.surface,padding:"11px 18px 9px",borderBottom:`1px solid ${T.border}`,flexShrink:0}}><div style={{display:"flex",alignItems:"center",gap:12}}><div style={{flexShrink:0}}><Logo s={34}/></div><div style={{flex:1,minWidth:0}}><div style={{display:"flex",alignItems:"baseline",gap:5}}><span style={{color:T.white,fontWeight:900,fontSize:14,letterSpacing:"-.3px"}}>CYCLING</span><span style={{color:T.accent,fontWeight:300,fontSize:14,letterSpacing:"2px"}}>COMPANION</span></div><div style={{display:"flex",gap:1,marginTop:2,marginBottom:2}}><div style={{height:2,flex:1,background:T.ro1,borderRadius:1}}/><div style={{height:2,flex:1,background:T.ro2,borderRadius:1}}/><div style={{height:2,flex:1,background:T.ro3,borderRadius:1}}/></div><div style={{color:T.muted,fontSize:10}}>{SUBS[ci]}</div></div>{user&&<button onClick={()=>setTab(nav.length-1)} style={{background:"none",border:"none",cursor:"pointer",flexShrink:0}}><div style={{width:30,height:30,borderRadius:"50%",background:user.avatar?"transparent":`linear-gradient(135deg,${T.accent},#6366f1)`,border:`2px solid ${user.sex==="feminin"?T.pink:T.accent}`,overflow:"hidden",display:"flex",alignItems:"center",justifyContent:"center"}}>{user.avatar?<img src={user.avatar} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<span style={{color:"#fff",fontWeight:800,fontSize:12}}>{(user.name||"U")[0].toUpperCase()}</span>}</div></button>}</div></div><div style={{flex:1,overflowY:"auto",padding:"16px 15px 22px",opacity:visible?1:0,transform:visible?"translateY(0)":"translateY(5px)",transition:"opacity .2s,transform .2s"}}>{screens[tab]}</div><div style={{background:T.surface,borderTop:`1px solid ${T.border}`,display:"flex",flexShrink:0}}>{nav.map((item,i)=><button key={i} onClick={()=>setTab(i)} style={{flex:1,background:"none",border:"none",padding:"9px 2px 7px",cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"center",gap:2}}><div style={{width:30,height:30,borderRadius:8,background:tab===i?T.accent+"22":"transparent",display:"flex",alignItems:"center",justifyContent:"center",fontSize:15,transition:"background .15s"}}>{item.i}</div><span style={{color:tab===i?T.accent:T.muted,fontSize:9,fontWeight:tab===i?700:500}}>{item.l}</span></button>)}</div></div>);}
